-- ==============================================================================
-- MCA Memories 2025–2027 Yearbook Database Seed
-- File: supabase/seed.sql
-- Description: 72 Editable placeholder memory questions (Numbered 1 through 72)
-- Note: Replace placeholder question text and descriptions with your final yearbook content.
-- ==============================================================================

ON CONFLICT (question_number) DO UPDATE
SET 
  question_text = EXCLUDED.question_text,
  description = EXCLUDED.description,
  is_active = EXCLUDED.is_active,
  updated_at = timezone('utc'::text, now());
